package me.prince.launcher

import androidx.compose.ui.text.ExperimentalTextApi
import androidx.compose.ui.text.font.Font
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontVariation
import androidx.compose.ui.text.font.FontWeight

private val WEIGHTS = listOf(FontWeight.Light, FontWeight.Normal, FontWeight.Medium, FontWeight.SemiBold, FontWeight.Bold)

// R.font.ui is generated by the build: Inter's variable font (app/fonts/inter.ttf, axes wght 100-900, opsz 14-32,
// SIL Open Font License, third_party/Inter-OFL.txt) unless local.properties names another one with ui.font.
@OptIn(ExperimentalTextApi::class)
private fun uiFont(opticalSize: Float) = FontFamily(
    WEIGHTS.map { weight ->
        Font(
            R.font.ui,
            weight,
            variationSettings = FontVariation.Settings(
                FontVariation.weight(weight.weight),
                FontVariation.Setting("opsz", opticalSize),
            ),
        )
    }
)

// Text and display optical sizes, like Apple's SF Pro Text / Display; display is for text 20sp and up
val UiText = uiFont(BuildConfig.UI_FONT_OPSZ_TEXT)
val UiDisplay = uiFont(BuildConfig.UI_FONT_OPSZ_DISPLAY)
